using NUnit.Framework;
using UnityEngine;
namespace SpatialSurvivor.Tests {
public class SurvivorArtTests {
 [TestCase("Mossling")][TestCase("EmberImp")][TestCase("CrystalGuardian")][TestCase("MoonWisp")][TestCase("ElderBloom")][TestCase("SkyMoth")][TestCase("StormDrake")][TestCase("Sporecap")][TestCase("RuneShaman")][TestCase("IronBeetle")][TestCase("FrostWitch")][TestCase("ThornSentinel")][TestCase("MoonRegent")]
 public void CreatureHasPaintedSkinAndSixWorkingJointClips(string name){var prefab=Resources.Load<GameObject>("Art/Creatures/"+name);Assert.That(prefab,Is.Not.Null);var go=Object.Instantiate(prefab);try{var skin=go.GetComponent<SkinnedMeshRenderer>();foreach(int index in skin.sharedMesh.triangles)Assert.That(index,Is.InRange(0,skin.sharedMesh.vertexCount-1),"Persisted mesh triangle must address a painted vertex");Assert.That(skin.bones.Length,Is.EqualTo(20));Assert.That(skin.sharedMesh.colors.Length,Is.EqualTo(skin.sharedMesh.vertexCount));Assert.That(skin.sharedMaterials.Length,Is.EqualTo(1));Assert.That(skin.sharedMaterial.shader.name,Is.EqualTo("Survivor/Storybook"));var a=go.GetComponent<SurvivorCreatureAnimator>();foreach(var clip in new[]{a.idle,a.walk,a.attack,a.hit,a.spawn,a.death})Assert.That(clip&&clip.length>0,Is.True);
  a.Respawn();Assert.That(a.Motion,Is.EqualTo(CreatureMotion.Spawn));a.Tick(.65f);Assert.That(a.Motion,Is.EqualTo(CreatureMotion.Idle));var arm=go.transform.Find("Rig/Body/ArmL");var rotation=arm.localRotation;a.Attack();a.Tick(.3f);Assert.That(Quaternion.Angle(rotation,arm.localRotation),Is.GreaterThan(15));float t=a.MotionTime;a.Tick(.1f,true);Assert.That(a.MotionTime,Is.EqualTo(t));a.Die();a.Attack();Assert.That(a.Motion,Is.EqualTo(CreatureMotion.Death));a.Tick(.45f);Assert.That(go.transform.Find("Rig").localScale.x,Is.LessThan(.1f));a.Respawn();a.Tick(.65f);Assert.That(go.transform.Find("Rig").localScale.x,Is.GreaterThan(.9f));
 }finally{Object.DestroyImmediate(go);}}
 [Test] public void WalkClockSurvivesSparseMovementUpdates(){var parent=new GameObject("test parent");var go=Object.Instantiate(Resources.Load<GameObject>("Art/Creatures/Mossling"),parent.transform);try{var a=go.GetComponent<SurvivorCreatureAnimator>();a.Respawn();a.Tick(.65f);parent.transform.position=Vector3.right*.1f;a.Tick(.01f);Assert.That(a.Motion,Is.EqualTo(CreatureMotion.Walk));float t=a.MotionTime;for(int i=0;i<5;i++)a.Tick(.01f);Assert.That(a.Motion,Is.EqualTo(CreatureMotion.Walk));Assert.That(a.MotionTime,Is.GreaterThan(t));a.Tick(.2f);Assert.That(a.Motion,Is.EqualTo(CreatureMotion.Idle));}finally{Object.DestroyImmediate(parent);}}
 [Test] public void EveryWeaponHasNewSourceMeshAndEverySkillCreates(){var parent=new GameObject("Magic test");try{foreach(SkillVisual kind in System.Enum.GetValues(typeof(SkillVisual))){var go=SurvivorVisualCatalog.Create(kind,parent.transform);var effect=go.GetComponent<SurvivorMagicEffect>();Assert.That(effect,Is.Not.Null);effect.Tick(.2f);Assert.That(go.GetComponentsInChildren<LineRenderer>().Length>0||go.GetComponent<SurvivorDomainField>()?.VertexCount>0,Is.True);}Assert.That(Resources.Load<Texture2D>("Art/MenuIllustration"),Is.Not.Null);Assert.That(Resources.Load<Texture2D>("Art/SkillAtlas"),Is.Not.Null);}finally{Object.DestroyImmediate(parent);}}
}
}
